#include <vector>

class Solution {
public:
    bool removeOnes(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        for (int r = 1; r < m; ++r) {
            bool same = true, inv = true;
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] != grid[0][c]) same = false;
                if (grid[r][c] != 1 - grid[0][c]) inv = false;
            }
            if (!same && !inv) return false;
        }
        return true;
    }
};

class Solution {
    public boolean removeOnes(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        for (int r = 1; r < m; r++) {
            boolean same = true, inv = true;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != grid[0][c]) same = false;
                if (grid[r][c] != 1 - grid[0][c]) inv = false;
            }
            if (!same && !inv) return false;
        }
        return true;
    }
}

