    const m = grid.length, n = grid[0].length;
    for (let r = 1; r < m; r++) {
        let same = true, inv = true;
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== grid[0][c]) same = false;
            if (grid[r][c] !== 1 - grid[0][c]) inv = false;
        }
        if (!same && !inv) return false;
    }
